import type { Bike, BikeCategory, BikeSpecs, Transmission } from '../types';
import { MOCK_LOCATIONS } from './locations.mock';

/**
 * Mock bike inventory. Replace with `GET /bikes` once the backend is available.
 * Images are WebP illustrations generated by `scripts/generate-bike-art.mjs` (swap in real photos
 * by replacing the files in /public/assets/bikes; names stay the same).
 */


/** The three views generated for every bike (see scripts/generate-bike-art.mjs). */
const IMAGE_VIEWS = ['studio view', 'close-up of the tank and engine', 'riding through the city at dusk'];

const ALL = MOCK_LOCATIONS.map((l) => l.id);

interface Seed {
  id: string;
  brand: string;
  model: string;
  year: number;
  category: BikeCategory;
  transmission: Transmission;
  description: string;
  rating: number;
  reviewCount: number;
  tag?: Bike['tag'];
  specs: BikeSpecs;
  features: string[];
  hourly: number;
  daily: number;
  kmPerDay: number;
  extraKm: number;
  deposit: number;
  status: Bike['availability']['status'];
  unitsLeft: number;
  locationIds?: string[];
}

const PETROL_POLICY =
  'Delivered with a full tank (or as noted on your handover sheet). Return with the same fuel level; any shortfall is charged at actual fuel cost plus a ₹50 refuelling fee.';
const EV_POLICY =
  'Delivered fully charged. Return with at least 20% battery. Charging is free at any ZPROO GO hub; there is no refuelling fee.';

const BASE_SERVICES = [
  'Helmet for the rider (ISI certified)',
  'Roadside assistance, 24×7',
  'Comprehensive insurance (third party + own damage, excess applies)',
  'RC and insurance copies in the storage box',
  'Sanitised before every rental',
];

function make(s: Seed): Bike {
  const electric = s.category === 'electric';
  const name = `${s.brand} ${s.model}`;
  return {
    id: s.id,
    name,
    brand: s.brand,
    model: s.model,
    year: s.year,
    category: s.category,
    transmission: s.transmission,
    fuelType: electric ? 'electric' : 'petrol',
    description: s.description,
    rating: s.rating,
    reviewCount: s.reviewCount,
    ...(s.tag ? { tag: s.tag } : {}),
    images: IMAGE_VIEWS.map((view, i) => ({
      src: `/assets/bikes/${s.id}-${i + 1}.webp`,
      alt: `${name}, ${view}`,
    })),
    specs: s.specs,
    features: s.features,
    pricing: { currency: 'INR', hourly: s.hourly, daily: s.daily, minHours: 4, kmPerDay: s.kmPerDay, extraKmCharge: s.extraKm },
    securityDeposit: s.deposit,
    fuelPolicy: electric ? EV_POLICY : PETROL_POLICY,
    includedServices: electric ? [...BASE_SERVICES, 'Free charging at all ZPROO GO hubs'] : BASE_SERVICES,
    availability: { status: s.status, unitsLeft: s.unitsLeft, locationIds: s.locationIds ?? ALL },
  };
}

const spec = (p: Partial<BikeSpecs> & Pick<BikeSpecs, 'engine' | 'power' | 'efficiency' | 'topSpeed' | 'weight' | 'seatHeight'>): BikeSpecs => ({
  fuelCapacity: '—',
  seats: 2,
  brakes: 'Disc / Drum, CBS',
  ...p,
});

